const price = Number(homePrice) || 0;
const pct = (Number(downPaymentPct) || 0) / 100;
const saved = Number(savedSoFar) || 0;
const monthly = Number(monthlySavings) || 0;
const required = price * pct;
const gap = Math.max(0, required - saved);
const monthsToGoal = monthly > 0 ? gap / monthly : 0;
const progressPct = required > 0 ? (saved / required) * 100 : 0;
return { progressPct, required, gap, monthsToGoal };
